// expect: exit 0
// screen: 3         RED ON YELLOW
// screen: 5 Back to normal
// screen: 7 tab:        here
// attr: 3 8 0x32
int main(void)
{
    cls();
    border(1);
    at(3, 8);
    ink(2);
    paper(6);
    print("RED ON YELLOW");
    at(5, 0);
    ink(0);
    paper(7);
    print("Back to normal");
    at(7, 0);
    print("tab:");
    tab(12);
    print("here");
    return 0;
}
